// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, Img, random, interpolate } from '../remotionShim';


export type FlickeringLightsProps = Record<string, any>;

const FlickeringLights: React.FC<FlickeringLightsProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  backgroundImage = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/c21b8bde9a4b47c2841b49a9eb0bb79b.png",
  flickerSpeed = 2,
  lightIntensity = 0.9,
  primaryLightColor = "#ffebc2",
  secondaryLightColor = "#ffffff",
  numberOfLights = 15,
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Generate deterministic properties for each light source
  const lights = useMemo(() => {
    return Array.from({ length: numberOfLights }).map((_, i) => {
      const isPrimary = random(`color-choice-${i}`) > 0.5;
      
      // Distribute evenly from left to right to guarantee a clear sequential chase
      const progress = i / Math.max(1, numberOfLights - 1);
      
      // Allow a tiny amount of horizontal jitter so it doesn't look perfectly rigid
      const xJitter = (random(`x-jitter-${i}`) - 0.5) * (width * 0.05);
      const baseX = width * 0.05 + progress * (width * 0.9);
      const x = Math.max(0, Math.min(width, baseX + xJitter));
      
      // Randomize Y across the screen height to spread them out vertically
      const y = height * 0.1 + random(`pos-y-${i}`) * height * 0.8;
      
      // Reduced size so individual "bulbs" are clearly visible and distinct
      const size = interpolate(random(`size-${i}`), [0, 1], [width * 0.05, width * 0.15]);
      
      return {
        id: i,
        x,
        y,
        size,
        seedOffset: Math.floor(random(`offset-${i}`) * 1000),
        color: isPrimary ? primaryLightColor : secondaryLightColor,
      };
    });
  }, [numberOfLights, width, height, primaryLightColor, secondaryLightColor]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      {/* Base Image Layer */}
      <Img
        src={backgroundImage}
        style={{
          width: "100%",
          height: "100%",
          objectFit: "cover",
          transition: "none",
        }}
      />

      {/* Sequential Chasing Lights Layer */}
      <AbsoluteFill style={{ mixBlendMode: "screen", transition: "none", pointerEvents: "none" }}>
        {lights.map((light) => {
          // Normalize the X position for the spatial left-to-right sweep
          const normX = light.x / width;
          
          // Determine cycle speed: Higher flickerSpeed prop = faster chase
          const cycleLength = Math.floor(interpolate(flickerSpeed, [1, 15], [150, 30]));
          const chaseProgress = (frame % cycleLength) / cycleLength; 
          
          // Calculate the relative position of the light compared to the chase head
          const relativePos = (chaseProgress - normX + 1) % 1;
          
          // Determine how wide the active illuminated portion of the sweep is (25% of the screen)
          const chaseWindow = 0.25; 
          const isChaseActive = relativePos < chaseWindow;
          
          let currentOpacity = 0;
          
          if (isChaseActive) {
            // Compute sharp ON/OFF flicker strictly while in the active chase zone
            // Flicker rate scales with the flickerSpeed prop
            const flickerRate = Math.floor(interpolate(flickerSpeed, [1, 15], [8, 2]));
            const stepFrame = Math.floor((frame + light.seedOffset) / Math.max(1, flickerRate));
            const flickerRandom = random(`flicker-val-${light.id}-${stepFrame}`);
            
            // Actual ON/OFF: 75% chance to be completely ON, 25% chance to be completely OFF
            const isOn = flickerRandom > 0.25;
            
            currentOpacity = isOn ? lightIntensity : 0;
          } else {
            // Strictly OFF when outside the chase sweep
            currentOpacity = 0;
          }

          return (
            <div
              key={light.id}
              style={{
                position: "absolute",
                left: light.x - light.size / 2,
                top: light.y - light.size / 2,
                width: light.size,
                height: light.size,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                opacity: currentOpacity,
                transition: "none",
              }}
            >
              {/* Outer Glow */}
              <div
                style={{
                  position: "absolute",
                  width: "100%",
                  height: "100%",
                  borderRadius: "50%",
                  background: `radial-gradient(circle, ${light.color} 0%, transparent 60%)`,
                  opacity: 0.8,
                  transition: "none",
                }}
              />
              {/* Inner bright bulb core to emphasize the on/off state */}
              <div
                style={{
                  position: "absolute",
                  width: "15%",
                  height: "15%",
                  borderRadius: "50%",
                  backgroundColor: "#ffffff",
                  boxShadow: `0 0 ${light.size * 0.1}px ${light.color}`,
                  opacity: 0.9,
                  transition: "none",
                }}
              />
            </div>
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default FlickeringLights;